+(function () {
+  const form = document.getElementById('prefs-form');
+  const errorEl = document.getElementById('notify-error');
+  const statusEl = document.getElementById('form-status');
+  const radios = form.querySelectorAll('input[name="notify"]');
+
+  function clearError() {
+    errorEl.hidden = true;
+    errorEl.textContent = '';
+    radios.forEach((r) => r.removeAttribute('aria-invalid'));
