+    statusEl.classList.remove('is-success');
+    statusEl.textContent = '';
+
+    const selected = form.querySelector('input[name="notify"]:checked');
+    if (!selected) {
+      showError('Please choose how you want to receive notifications.');
+      radios[0].focus();
+      return;
+    }
+
+    clearError();
+    const labelText = form.querySelector('label[for="' + selected.id + '"] .radio-option__title').textContent;
+    statusEl.classList.add('is-success');
+    statusEl.textContent = 'Preferences saved. You\u2019ll receive notifications via ' + labelText + '.';
+  });
+})();
